<?php $titles=['brands'=>'Brands','vehicle_manufacturers'=>'Bike manufacturers','vehicle_models'=>'Bike models','vehicle_variants'=>'Bike variants','tax_rates'=>'Product tax rates']; ?>
<section class="page-heading"><div><h1><?= e($titles[$type]) ?></h1><p>Shop-specific catalogue. Changes never imply product compatibility.</p></div><a class="button" href="<?= e(url('/products')) ?>">Products</a></section><nav class="product-actions master-tabs"><?php foreach($titles as $tab=>$label): ?><a class="button <?= $tab===$type?'button-primary':'' ?>" href="<?= e(url('/product-masters')) ?>&amp;type=<?= e($tab) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
<?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?><?php if($notice): ?><div class="notice" role="status"><?= e($notice) ?></div><?php endif; ?>
<form class="product-filters" method="get" action="index.php"><input type="hidden" name="route" value="/product-masters"><input type="hidden" name="type" value="<?= e($type) ?>"><label>Search<input name="q" value="<?= e($q) ?>"></label><button class="button">Search</button></form>
<section class="surface product-section"><h2>Add <?= e(strtolower($titles[$type])) ?></h2><form method="post" action="<?= e(url('/product-masters')) ?>" class="product-fields"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="type" value="<?= e($type) ?>"><label>Name<input name="name" required maxlength="<?= $type==='tax_rates'?80:150 ?>" value="<?= e(!isset($old['id'])?($old['name']??''):'') ?>"></label><?php if($type==='tax_rates'): ?><label>Percentage<input name="rate" type="number" min="0" max="100" step="0.01" required></label><?php endif; ?><?php if($type==='vehicle_models' || $type==='vehicle_variants'): $parent=$type==='vehicle_models'?'manufacturer_id':'model_id';$parentTable=$type==='vehicle_models'?'vehicle_manufacturers':'vehicle_models'; ?><label>Parent<select name="<?= e($parent) ?>" required><option value="">Choose parent</option><?php foreach($masters[$parentTable] as $entry): ?><option value="<?= (int)$entry['id'] ?>"><?= e($entry['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?><button class="button button-primary">Add</button></form></section>
<div class="surface table-scroll"><table><thead><tr><th>Name</th><?php if($type==='brands'): ?><th>Linked products</th><?php endif; ?><th>Details</th><th>Edit</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['name']) ?></td><?php if($type==='brands'): ?><td><a href="<?= e(url('/products')) ?>&amp;status=all&amp;brand_id=<?= (int)$row['id'] ?>"><?= (int)$row['product_count'] ?> products</a></td><?php endif; ?><td><?php if(isset($row['status'])): ?><?= e(ucfirst($row['status'])) ?><?php endif; ?><?php if(isset($row['rate'])): ?> · <?= e($row['rate']) ?>%<?php endif; ?><?php if(isset($row['manufacturer_id'])): foreach($masters['vehicle_manufacturers'] as $parent)if($parent['id']===$row['manufacturer_id'])echo e($parent['name']); endif; ?><?php if(isset($row['model_id'])): foreach($masters['vehicle_models'] as $parent)if($parent['id']===$row['model_id'])echo e($parent['name']); endif; ?></td><td><details><summary>Edit</summary><form class="master-edit" method="post" action="<?= e(url('/product-masters')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="type" value="<?= e($type) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Name<input name="name" required maxlength="<?= $type==='tax_rates'?80:150 ?>" value="<?= e($row['name']) ?>"></label><?php if(isset($row['status'])): ?><label>Status<select name="status"><option value="active">Active</option><option value="inactive" <?= $row['status']==='inactive'?'selected':'' ?>>Inactive</option></select></label><?php endif; ?><?php if(isset($row['rate'])): ?><label>Percentage<input name="rate" type="number" min="0" max="100" step="0.01" value="<?= e($row['rate']) ?>" required></label><?php endif; ?><?php foreach(['manufacturer_id','model_id'] as $field): if(isset($row[$field])): ?><input type="hidden" name="<?= e($field) ?>" value="<?= (int)$row[$field] ?>"><?php endif; endforeach; ?><button class="button">Save</button></form><?php if($type==='brands'): ?><form method="post" action="<?= e(url('/product-masters')) ?>" data-product-confirm="Delete this unused brand? Linked products will block deletion."><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="type" value="brands"><input type="hidden" name="action" value="delete_brand"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="danger-button">Delete unused brand</button></form><?php endif; ?></details></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="empty-state compact"><h3>No matching entries</h3></div><?php endif; ?></div>
